/**
 * Ethiopian Calendar Utility
 *
 * Ethiopian fiscal year runs Hamle 1 to Sene 30 (approximately July 8 to July 7).
 * Used for fiscal reporting periods required by MoR.
 */

const ETHIOPIAN_MONTHS_AM = [
    'ßêÿßê╡ßè¿ßê¿ßê¥',
    'ßîÑßëàßê¥ßë╡',
    'ßèàßï│ßê¡',
    'ßë│ßèàßêúßêÑ',
    'ßîÑßê¡',
    'ßï¿ßè½ßë▓ßë╡',
    'ßêÿßîïßëóßë╡',
    'ßêÜßï½ßï¥ßï½',
    'ßîìßèòßëªßë╡',
    'ßê░ßèö',
    'ßêÉßê¥ßêî',
    'ßèÉßêÉßê┤',
    'ßî│ßîëßê£',
];

const ETHIOPIAN_MONTHS_EN = [
    'Meskerem',
    'Tikimt',
    'Hidar',
    'Tahsas',
    'Tir',
    'Yekatit',
    'Megabit',
    'Miazia',
    'Ginbot',
    'Sene',
    'Hamle',
    'Nehase',
    'Pagume',
];

/**
 * Approximate Ethiopian date from Gregorian date.
 * Ethiopian year is ~7-8 years behind Gregorian.
 * This is a simplification ΓÇö exact conversion requires astronomical calculations.
 */
export function gregorianToEthiopianApprox(date: Date): {
    year: number;
    month: number;
    monthAm: string;
    monthEn: string;
    day: number;
} {
    // Ethiopian new year is approximately September 11 (Gregorian)
    const ethYear = date.getFullYear() - 8;
    const ethNewYear = new Date(date.getFullYear(), 8, 11); // Sept 11

    let daysSinceNewYear: number;

    if (date >= ethNewYear) {
        daysSinceNewYear = Math.floor(
            (date.getTime() - ethNewYear.getTime()) / (1000 * 60 * 60 * 24)
        );
    } else {
        const prevNewYear = new Date(date.getFullYear() - 1, 8, 11);
        daysSinceNewYear = Math.floor(
            (date.getTime() - prevNewYear.getTime()) / (1000 * 60 * 60 * 24)
        );
    }

    const ethMonth = Math.min(12, Math.floor(daysSinceNewYear / 30));
    const ethDay = (daysSinceNewYear % 30) + 1;

    return {
        year: ethNewYear.getFullYear() - 8,
        month: ethMonth + 1,
        monthAm: ETHIOPIAN_MONTHS_AM[ethMonth],
        monthEn: ETHIOPIAN_MONTHS_EN[ethMonth],
        day: ethDay,
    };
}

/**
 * Get the start month index of the Ethiopian fiscal year.
 * Ethiopian fiscal year starts Hamle 1 (month index 10, 0-based).
 */
export function getFiscalYearStartMonth(): number {
    return 10; // Hamle
}

/**
 * Ethiopian fiscal year label for a Gregorian calendar year.
 */
export function ethiopianFiscalYearLabel(gregorianYear: number): string {
    const ethYear = gregorianYear - 8;
    return `${ethYear}/${ethYear + 1} (${ETHIOPIAN_MONTHS_EN[10]} 1 ΓÇö ${ETHIOPIAN_MONTHS_EN[9]} 30)`;
}

import { issueGatewaySessionToken, type GatewaySessionBundle } from '@/lib/auth/gateway-session';
import {
    buildOfflineDeviceAuthorization,
    buildOfflineStaffOutagePolicy,
} from '@/lib/auth/offline-authz';
import { buildGatewayDiscoveryRecord, type GatewayDiscoveryRecord } from '@/lib/lan/discovery';
import {
    buildGatewayHealthSnapshot,
    type GatewayHealthSnapshot,
    type StoreGatewayConfig,
} from '@/lib/gateway/config';
import type { DeviceProfile, HardwareDeviceType } from '@/lib/devices/config';

export interface GatewayBootstrapPayload {
    discovery: GatewayDiscoveryRecord;
    health: GatewayHealthSnapshot;
    session: GatewaySessionBundle;
    endpoints: {
        health: string;
        bootstrap: string;
    };
}

export interface CreateGatewayBootstrapPayloadInput {
    deviceId: string;
    restaurantId: string;
    locationId: string;
    gatewayId: string;
    gatewayHost: string;
    mqttBrokerUrl: string;
    healthPort: number;
    deviceType?: HardwareDeviceType;
    deviceProfile?: DeviceProfile | null;
    identityVersion?: number;
    operatingMode?: GatewayHealthSnapshot['operatingMode'];
}

function buildBootstrapConfig(input: CreateGatewayBootstrapPayloadInput): StoreGatewayConfig {
    return {
        restaurantId: input.restaurantId,
        locationId: input.locationId,
        gatewayId: input.gatewayId,
        runtime: 'node-service',
        hostTarget: 'mini-pc',
        lanTransport: 'mqtt',
        mqttBrokerUrl: input.mqttBrokerUrl,
        fiscalContinuityMode: 'local-signing',
        queueDurabilityMode: 'persistent-local-queue',
        healthPort: input.healthPort,
        defaultOperatingMode: input.operatingMode ?? 'offline-local',
    };
}

export function createGatewayBootstrapPayload(
    input: CreateGatewayBootstrapPayloadInput
): GatewayBootstrapPayload {
    const config = buildBootstrapConfig(input);
    const health = buildGatewayHealthSnapshot(
        config,
        input.operatingMode ?? config.defaultOperatingMode
    );

    const offlineAuthorization = buildOfflineDeviceAuthorization({
        deviceType: input.deviceType ?? 'pos',
        deviceProfile: input.deviceProfile ?? null,
    });
    const staffOutagePolicy = buildOfflineStaffOutagePolicy({
        deviceType: input.deviceType ?? 'pos',
        deviceProfile: input.deviceProfile ?? null,
    });
    const issuedAt = new Date();
    const offlineAccessExpiresAt = new Date(
        issuedAt.getTime() + offlineAuthorization.ttlMinutes * 60 * 1000
    ).toISOString();

    return {
        discovery: buildGatewayDiscoveryRecord(config),
        health,
        session: {
            deviceId: input.deviceId,
            restaurantId: input.restaurantId,
            locationId: input.locationId,
            gatewayId: input.gatewayId,
            deviceType: input.deviceType ?? 'pos',
            deviceProfile: input.deviceProfile ?? null,
            identityVersion: input.identityVersion ?? 1,
            authorizations: offlineAuthorization.capabilities,
            offlineAccessExpiresAt,
            staffOutagePolicy: {
                ...staffOutagePolicy,
                issuedAt: issuedAt.toISOString(),
            },
        },
        endpoints: {
            health: `http://${input.gatewayHost}:${input.healthPort}/health`,
            bootstrap: `http://${input.gatewayHost}:${input.healthPort}/bootstrap`,
        },
    };
}

import type { GatewaySessionClaims } from '@/lib/auth/gateway-session';
import { logger } from '@/lib/logger';

interface TopicTenant {
    restaurantId: string;
    locationId: string;
}

export function parseTopicTenant(topic: string): TopicTenant | null {
    const parts = topic.split('/');
    if (!topic.startsWith('lole/v1/restaurants/') || parts.length < 7) {
        return null;
    }

    return {
        restaurantId: parts[3],
        locationId: parts[5],
    };
}

export function isSystemTopic(topic: string): boolean {
    const parts = topic.split('/');
    return parts.length >= 8 && parts[6] === 'system';
}

export interface AclDecision {
    allowed: boolean;
    reason: string;
}

export function authorizePublish(topic: string, claims: GatewaySessionClaims | null): AclDecision {
    const tenant = parseTopicTenant(topic);

    if (!tenant) {
        return { allowed: false, reason: `Unknown topic format: ${topic}` };
    }

    if (!claims) {
        return { allowed: false, reason: 'Authentication required to publish' };
    }

    if (claims.restaurantId !== tenant.restaurantId || claims.locationId !== tenant.locationId) {
        return {
            allowed: false,
            reason: `Client ${claims.restaurantId}/${claims.locationId} may not publish to ${tenant.restaurantId}/${tenant.locationId}`,
        };
    }

    if (isSystemTopic(topic) && !claims.authorizations.includes('gateway.bootstrap')) {
        return {
            allowed: false,
            reason: 'Only gateway-privileged clients may publish to system topics',
        };
    }

    const deviceType = claims.deviceType ?? 'unknown';
    const topicGroup = topic.split('/')[6] ?? '';
    const kdsGroups = ['kds', 'cooking', 'expedite'];
    const posGroups = ['orders', 'tables', 'sessions'];
    const isKdsGroup = kdsGroups.some(g => topicGroup.startsWith(g));
    const isPosGroup = posGroups.some(g => topicGroup.startsWith(g));

    if (deviceType === 'kds' && isPosGroup) {
        return {
            allowed: false,
            reason: `KDS devices may not publish to ${topicGroup} topics`,
        };
    }

    return { allowed: true, reason: 'OK' };
}

export function authorizeSubscribe(
    topic: string,
    claims: GatewaySessionClaims | null
): AclDecision {
    const tenant = parseTopicTenant(topic);

    if (!tenant) {
        return { allowed: false, reason: `Unknown topic format: ${topic}` };
    }

    if (!claims) {
        return { allowed: false, reason: 'Authentication required to subscribe' };
    }

    if (claims.restaurantId !== tenant.restaurantId || claims.locationId !== tenant.locationId) {
        return {
            allowed: false,
            reason: `Client ${claims.restaurantId}/${claims.locationId} may not subscribe to ${tenant.restaurantId}/${tenant.locationId}`,
        };
    }

    return { allowed: true, reason: 'OK' };
}

import { createServer } from 'http';
import { mkdirSync, openSync, closeSync } from 'fs';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { logger } from '../logger';
import { getDeviceContext } from '../api/authz';
import { resolveGatewayIdentityVersion } from '../auth/offline-authz';
import { createGatewayBootstrapPayload } from './bootstrap';
import { DeviceProfileSchema, HardwareDeviceTypeSchema } from '../devices/config';
import { createGatewayBroker, type BrokerInstance } from './mqtt-broker';

interface StandaloneGatewayConfig {
    restaurantId: string;
    locationId: string;
    gatewayId: string;
    host: string;
    port: number;
    mqttBrokerUrl: string;
    dataDir: string;
    bootstrapSecret: string;
}

function getRequiredEnv(name: string): string {
    const value = process.env[name];
    if (!value) {
        throw new Error(`${name} is required`);
    }

    return value;
}

export function getStandaloneGatewayConfig(): StandaloneGatewayConfig {
    const host = process.env.GATEWAY_HOST ?? '127.0.0.1';
    const port = Number(process.env.GATEWAY_HEALTH_PORT ?? '8787');
    const dataDir = process.env.STORE_GATEWAY_DATA_DIR ?? join(process.cwd(), '.local-gateway');

    return {
        restaurantId: getRequiredEnv('RESTAURANT_ID'),
        locationId: getRequiredEnv('LOCATION_ID'),
        gatewayId: process.env.GATEWAY_ID ?? `gateway-${getRequiredEnv('LOCATION_ID')}`,
        host,
        port,
        mqttBrokerUrl: process.env.LAN_MQTT_URL ?? `ws://${host}:1884/mqtt`,
        dataDir,
        bootstrapSecret: getRequiredEnv('GATEWAY_BOOTSTRAP_SECRET'),
    };
}

export function initPersistentStorage(dataDir: string): string {
    mkdirSync(dataDir, { recursive: true });
    const journalPath = join(dataDir, 'local-journal.db');
    const handle = openSync(journalPath, 'a');
    closeSync(handle);
    return journalPath;
}

async function readBody(request: import('http').IncomingMessage): Promise<string> {
    const chunks: Buffer[] = [];

    for await (const chunk of request) {
        chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
    }

    return Buffer.concat(chunks).toString('utf8');
}

export async function startStandaloneGatewayServer(
    config: StandaloneGatewayConfig = getStandaloneGatewayConfig()
): Promise<{ broker: BrokerInstance; close(): Promise<void> }> {
    const journalPath = initPersistentStorage(config.dataDir);

    const broker = createGatewayBroker(config.host, 1884);
    await broker.start();

    const server = createServer(async (request, response) => {
        const url = new URL(request.url ?? '/', `http://${config.host}:${config.port}`);

        if (url.pathname === '/health') {
            const brokerMetrics = broker.metrics;
            const payload = JSON.stringify({
                health: {
                    gatewayId: config.gatewayId,
                    restaurantId: config.restaurantId,
                    locationId: config.locationId,
                    operatingMode: 'offline-local',
                    lanTransport: 'mqtt',
                    fiscalContinuityMode: 'local-signing',
                    queueDurabilityMode: 'persistent-local-queue',
                    timestamp: new Date().toISOString(),
                    journalPath,
                    broker: {
                        connectedClients: brokerMetrics.connectedClients,
                        messagesPublished: brokerMetrics.messagesPublished,
                        messagesReceived: brokerMetrics.messagesReceived,
                        uptimeSeconds: brokerMetrics.uptimeSeconds,
                    },
                },
            });

            response.writeHead(200, { 'content-type': 'application/json' });
            response.end(payload);
            return;
        }

        if (url.pathname === '/metrics') {
            const mqttBrokerConnected = broker.broker.closed ? 0 : 1;
            const metricsPayload = [
                '# HELP gateway_uptime_seconds Time since gateway started',
                '# TYPE gateway_uptime_seconds gauge',
                `gateway_uptime_seconds ${broker.metrics.uptimeSeconds}`,
                '# HELP gateway_mqtt_connections_total Current connected MQTT clients',
                '# TYPE gateway_mqtt_connections_total gauge',
                `gateway_mqtt_connections_total ${broker.metrics.connectedClients}`,
                '# HELP gateway_mqtt_messages_published_total MQTT messages published',
                '# TYPE gateway_mqtt_messages_published_total counter',
                `gateway_mqtt_messages_published_total ${broker.metrics.messagesPublished}`,
                '# HELP gateway_mqtt_messages_received_total MQTT messages received',
                '# TYPE gateway_mqtt_messages_received_total counter',
                `gateway_mqtt_messages_received_total ${broker.metrics.messagesReceived}`,
                '# HELP gateway_health_status 1 if healthy',
                '# TYPE gateway_health_status gauge',
                `gateway_health_status ${mqttBrokerConnected}`,
                '',
            ].join('\n');

            response.writeHead(200, { 'content-type': 'text/plain' });
            response.end(metricsPayload);
            return;
        }

        if (url.pathname === '/bootstrap' && request.method === 'POST') {
            const body = await readBody(request);
            const parsed = body ? (JSON.parse(body) as Record<string, unknown>) : {};
            let payload: ReturnType<typeof createGatewayBootstrapPayload> | null = null;

            if (request.headers['x-device-token']) {
                const authRequest = new Request(url, {
                    method: request.method,
                    headers: Object.entries(request.headers).reduce(
                        (acc, [key, value]) => {
                            if (typeof value === 'string') acc[key] = value;
                            if (Array.isArray(value)) acc[key] = value.join(', ');
                            return acc;
                        },
                        {} as Record<string, string>
                    ),
                    body: body.length > 0 ? body : undefined,
                });
                const context = await getDeviceContext(authRequest);
                if (!context.ok) {
                    response.writeHead(401, { 'content-type': 'application/json' });
                    response.end(JSON.stringify({ error: 'Unauthorized bootstrap request' }));
                    return;
                }
                const deviceType = HardwareDeviceTypeSchema.safeParse(context.device.device_type)
                    .success
                    ? (context.device.device_type as
                          | 'pos'
                          | 'kds'
                          | 'kiosk'
                          | 'digital_menu'
                          | 'terminal')
                    : 'pos';
                const deviceProfile = DeviceProfileSchema.safeParse(context.device.device_profile)
                    .success
                    ? context.device.device_profile
                    : null;

                payload = createGatewayBootstrapPayload({
                    deviceId: context.device.id,
                    restaurantId: context.restaurantId,
                    locationId: context.device.location_id ?? config.locationId,
                    gatewayId: config.gatewayId,
                    gatewayHost: config.host,
                    mqttBrokerUrl: config.mqttBrokerUrl,
                    healthPort: config.port,
                    deviceType,
                    deviceProfile,
                    identityVersion: resolveGatewayIdentityVersion(context.device.metadata),
                    operatingMode: 'offline-local',
                });
            } else if (
                process.env.NODE_ENV !== 'production' &&
                request.headers['x-gateway-bootstrap-secret'] === config.bootstrapSecret
            ) {
                logger.warn(
                    '[Gateway] Bootstrap via static secret used ΓÇö only allowed in non-production'
                );
                const deviceId =
                    typeof parsed.deviceId === 'string' && parsed.deviceId.length > 0
                        ? parsed.deviceId
                        : 'bootstrap-device';
                const locationId =
                    typeof parsed.locationId === 'string' && parsed.locationId.length > 0
                        ? parsed.locationId
                        : config.locationId;
                payload = createGatewayBootstrapPayload({
                    deviceId,
                    restaurantId: config.restaurantId,
                    locationId,
                    gatewayId: config.gatewayId,
                    gatewayHost: config.host,
                    mqttBrokerUrl: config.mqttBrokerUrl,
                    healthPort: config.port,
                    operatingMode: 'offline-local',
                });
            }

            if (!payload) {
                response.writeHead(401, { 'content-type': 'application/json' });
                response.end(JSON.stringify({ error: 'Unauthorized bootstrap request' }));
                return;
            }

            response.writeHead(200, { 'content-type': 'application/json' });
            response.end(JSON.stringify(payload));
            return;
        }

        response.writeHead(404, { 'content-type': 'application/json' });
        response.end(JSON.stringify({ error: 'Not found' }));
    });

    await new Promise<void>((resolve, reject) => {
        server.once('error', reject);
        server.listen(config.port, config.host, () => resolve());
    });

    logger.info('[Gateway] Standalone gateway started', {
        gatewayId: config.gatewayId,
        host: config.host,
        port: config.port,
        brokerPort: 1884,
        journalPath,
    });

    return {
        broker,
        close: async () => {
            await new Promise<void>((resolve, reject) => {
                server.close(error => {
                    if (error) reject(error);
                    else resolve();
                });
            });
            await broker.stop();
        },
    };
}

const executedPath = process.argv[1];
const isDirectRun =
    executedPath !== undefined && import.meta.url === pathToFileURL(executedPath).href;

if (isDirectRun) {
    void startStandaloneGatewayServer()
        .then(({ broker, close }) => {
            const shutdown = async (): Promise<void> => {
                logger.info('[Gateway] Shutting down...');
                await close();
                process.exit(0);
            };
            process.on('SIGINT', shutdown);
            process.on('SIGTERM', shutdown);
        })
        .catch(error => {
            logger.error('[Gateway] Failed to start standalone gateway', error);
            process.exitCode = 1;
        });
}

import { openSync, closeSync, readFileSync, writeFileSync, existsSync, mkdirSync } from 'fs';
import { join } from 'path';
import { logger } from '@/lib/logger';
import { GatewayError, GatewayErrorCode } from '@/lib/gateway/errors';

export interface QueueEntry {
    id: string;
    type: string;
    aggregate: string;
    aggregateId: string;
    payload: Record<string, unknown>;
    restaurantId: string;
    locationId: string;
    enqueuedAt: string;
    retryCount: number;
    maxRetries: number;
}

interface QueueStore {
    entries: QueueEntry[];
    lastSequence: number;
}

export class PersistentLocalQueue {
    private readonly filePath: string;
    private store: QueueStore;
    private readonly maxRetries: number;

    constructor(dataDir: string, maxRetries = 5) {
        mkdirSync(dataDir, { recursive: true });
        this.filePath = join(dataDir, 'command-queue.json');
        this.maxRetries = maxRetries;
        this.store = this.load();
    }

    private load(): QueueStore {
        try {
            if (existsSync(this.filePath)) {
                const raw = readFileSync(this.filePath, 'utf8');
                const parsed = JSON.parse(raw) as QueueStore;
                return {
                    entries: Array.isArray(parsed.entries)
                        ? parsed.entries.filter(e => e && typeof e.id === 'string')
                        : [],
                    lastSequence: typeof parsed.lastSequence === 'number' ? parsed.lastSequence : 0,
                };
            }
        } catch (err) {
            logger.warn('[PersistentQueue] Failed to load queue, starting fresh', {
                error: err instanceof Error ? err.message : String(err),
            });
        }
        return { entries: [], lastSequence: 0 };
    }

    private persist(): void {
        try {
            writeFileSync(this.filePath, JSON.stringify(this.store), 'utf8');
        } catch (err) {
            throw new GatewayError(
                GatewayErrorCode.JOURNAL_WRITE_FAILED,
                'Failed to persist command queue',
                { filePath: this.filePath, error: String(err) }
            );
        }
    }

    enqueue(
        entry: Omit<QueueEntry, 'id' | 'enqueuedAt' | 'retryCount' | 'maxRetries'>
    ): QueueEntry {
        const id = crypto.randomUUID();
        const queueEntry: QueueEntry = {
            ...entry,
            id,
            enqueuedAt: new Date().toISOString(),
            retryCount: 0,
            maxRetries: this.maxRetries,
        };

        this.store.entries.push(queueEntry);
        this.store.lastSequence++;
        this.persist();

        logger.debug('[PersistentQueue] Enqueued command', {
            id,
            type: entry.type,
            queueSize: this.store.entries.length,
        });

        return queueEntry;
    }

    dequeue(): QueueEntry | null {
        if (this.store.entries.length === 0) {
            return null;
        }

        const entry = this.store.entries.shift()!;
        this.persist();
        return entry;
    }

    peek(): QueueEntry | null {
        if (this.store.entries.length === 0) {
            return null;
        }
        return this.store.entries[0];
    }

    ack(id: string): void {
        this.store.entries = this.store.entries.filter(e => e.id !== id);
        this.persist();
    }

    nack(id: string): QueueEntry | null {
        const entry = this.store.entries.find(e => e.id === id);
        if (!entry) return null;

        entry.retryCount++;

        if (entry.retryCount >= this.maxRetries) {
            this.store.entries = this.store.entries.filter(e => e.id !== id);
            this.persist();
            logger.warn('[PersistentQueue] Command exceeded max retries, discarded', {
                id,
                type: entry.type,
                retryCount: entry.retryCount,
            });
            return null;
        }

        this.persist();
        return entry;
    }

    getAll(): QueueEntry[] {
        return [...this.store.entries];
    }

    size(): number {
        return this.store.entries.length;
    }

    clear(): void {
        this.store = { entries: [], lastSequence: 0 };
        this.persist();
    }
}

export interface EscPosLineItem {
    name: string;
    quantity: number;
    unit_price: number;
    total_price: number;
    notes?: string | null;
}

export interface EscPosTaxLine {
    label: string;
    amount: number;
}

export interface EscPosReceiptPayload {
    restaurant_name: string;
    restaurant_tin?: string | null;
    transaction_number: string;
    printed_at: string;
    order_label?: string | null;
    payment_label?: string | null;
    currency?: string;
    language?: 'en' | 'am';
    items: EscPosLineItem[];
    taxes?: EscPosTaxLine[];
    subtotal: number;
    total: number;
    footer_lines?: string[];
    fiscal_qr_payload?: string | null;
    fiscal_warning?: string | null;
}

const ESC = 0x1b;
const GS = 0x1d;
const LF = 0x0a;

function textBytes(input: string): number[] {
    return Array.from(new TextEncoder().encode(input));
}

function newline(text: string): number[] {
    return [...textBytes(text), LF];
}

function padRight(value: string, width: number): string {
    return value.length >= width ? value.slice(0, width) : value.padEnd(width, ' ');
}

function padLeft(value: string, width: number): string {
    return value.length >= width ? value.slice(0, width) : value.padStart(width, ' ');
}

function money(value: number, currency: string): string {
    return `Br ${value.toFixed(2)}`;
}

function qrStoreBytes(data: string): number[] {
    const payload = textBytes(data);
    const length = payload.length + 3;
    const pL = length % 256;
    const pH = Math.floor(length / 256);

    return [GS, 0x28, 0x6b, pL, pH, 0x31, 0x50, 0x30, ...payload];
}

function qrPrintBytes(): number[] {
    return [GS, 0x28, 0x6b, 0x03, 0x00, 0x31, 0x51, 0x30];
}

function qrSizeBytes(size: number): number[] {
    return [GS, 0x28, 0x6b, 0x03, 0x00, 0x31, 0x43, Math.max(3, Math.min(12, size))];
}

function qrErrorCorrectionBytes(): number[] {
    return [GS, 0x28, 0x6b, 0x03, 0x00, 0x31, 0x45, 0x31];
}

async function encodeWithOptionalLibrary(
    payload: EscPosReceiptPayload
): Promise<Uint8Array | null> {
    try {
        interface ReceiptPrinterEncoderInstance {
            initialize: () => void;
            align: (alignment: string) => void;
            line: (text: string) => void;
            newline: () => void;
            bold: (enabled: boolean) => void;
            qrcode: (data: string) => void;
            cut: () => void;
            encode: () => Uint8Array;
        }
        interface EncoderModule {
            default?: new (options: { language: string }) => ReceiptPrinterEncoderInstance;
            ReceiptPrinterEncoder?: new (options: {
                language: string;
            }) => ReceiptPrinterEncoderInstance;
        }
        const importer = new Function('moduleName', 'return import(moduleName);') as (
            value: string
        ) => Promise<EncoderModule>;
        const encoderModule = await importer('@point-of-sale/receipt-printer-encoder');
        const ReceiptPrinterEncoder =
            encoderModule?.default ?? encoderModule?.ReceiptPrinterEncoder;
        if (!ReceiptPrinterEncoder) {
            return null;
        }

        const encoder = new ReceiptPrinterEncoder({
            language: 'esc-pos',
        });
        const isAmharic = payload.language === 'am';
        const labels = isAmharic
            ? {
                  tin: 'ßë▓ßèò',
                  txn: 'ßï¿ßîìßëÑßï¡ßë╡ ßëüßîÑßê¡',
                  subtotal: 'ßï╡ßê¥ßê¡ ßïïßîï',
                  total: 'ßîáßëàßêïßêï ßïïßîï',
                  payment: 'ßï¿ßè¡ßììßï½ ßïÿßï┤',
                  footer: 'ßêÄßêî ßê¼ßê╡ßë╢ßê½ßèòßë╡ ßèªßèñßê╡',
              }
            : {
                  tin: 'TIN',
                  txn: 'Txn',
                  subtotal: 'Subtotal',
                  total: 'TOTAL',
                  payment: 'Payment',
                  footer: 'lole Restaurant OS',
              };

        encoder.initialize();
        encoder.align('center');
        encoder.line(payload.restaurant_name);

        if (payload.restaurant_tin) {
            encoder.line(`${labels.tin}: ${payload.restaurant_tin}`);
        }

        encoder.line(`${labels.txn}: ${payload.transaction_number}`);
        encoder.line(payload.printed_at);
        encoder.newline();
        encoder.align('left');

        payload.items.forEach(item => {
            encoder.line(
                `${item.quantity}x ${item.name} ${money(item.total_price, payload.currency ?? 'ETB')}`
            );
            if (item.notes) {
                encoder.line(`  ${item.notes}`);
            }
        });

        encoder.newline();
        encoder.line(`${labels.subtotal} ${money(payload.subtotal, payload.currency ?? 'ETB')}`);
        payload.taxes?.forEach(tax => {
            encoder.line(`${tax.label} ${money(tax.amount, payload.currency ?? 'ETB')}`);
        });
        encoder.bold(true);
        encoder.line(`${labels.total} ${money(payload.total, payload.currency ?? 'ETB')}`);
        encoder.bold(false);

        if (payload.fiscal_warning) {
            encoder.newline();
            encoder.line(payload.fiscal_warning);
        }

        if (payload.fiscal_qr_payload) {
            encoder.newline();
            encoder.qrcode(payload.fiscal_qr_payload);
        }

        payload.footer_lines?.forEach(line => encoder.line(line));
        encoder.line(labels.footer);
        encoder.newline();
        encoder.cut();
        return encoder.encode();
    } catch {
        return null;
    }
}

export async function encodeReceiptToEscPos(payload: EscPosReceiptPayload): Promise<Uint8Array> {
    const libraryResult = await encodeWithOptionalLibrary(payload);
    if (libraryResult) {
        return libraryResult;
    }

    const currency = payload.currency ?? 'ETB';
    const isAmharic = payload.language === 'am';
    const labels = isAmharic
        ? {
              tin: 'ßë▓ßèò',
              txn: 'ßï¿ßîìßëÑßï¡ßë╡ ßëüßîÑßê¡',
              subtotal: 'ßï╡ßê¥ßê¡ ßïïßîï',
              total: 'ßîáßëàßêïßêï ßïïßîï',
              payment: 'ßï¿ßè¡ßììßï½ ßïÿßï┤',
              separator: 'ΓöÇ'.repeat(42),
              footer: 'ßêÄßêî ßê¼ßê╡ßë╢ßê½ßèòßë╡ ßèªßèñßê╡',
          }
        : {
              tin: 'TIN',
              txn: 'Txn',
              subtotal: 'Subtotal',
              total: 'TOTAL',
              payment: 'Payment',
              separator: '-'.repeat(42),
              footer: 'lole Restaurant OS',
          };

    const bytes: number[] = [];
    bytes.push(ESC, 0x40);
    bytes.push(ESC, 0x61, 0x01);
    bytes.push(ESC, 0x45, 0x01, ...newline(payload.restaurant_name), ESC, 0x45, 0x00);

    if (payload.restaurant_tin) {
        bytes.push(...newline(`${labels.tin}: ${payload.restaurant_tin}`));
    }

    bytes.push(...newline(`${labels.txn}: ${payload.transaction_number}`));
    bytes.push(...newline(payload.printed_at));
    if (payload.order_label) {
        bytes.push(...newline(payload.order_label));
    }

    bytes.push(...newline(labels.separator));
    bytes.push(ESC, 0x61, 0x00);

    payload.items.forEach(item => {
        bytes.push(...newline(`${item.quantity}x ${item.name}`));
        bytes.push(
            ...newline(
                `${padRight(money(item.unit_price, currency), 20)}${padLeft(money(item.total_price, currency), 22)}`
            )
        );
        if (item.notes) {
            bytes.push(...newline(`  ${item.notes}`));
        }
    });

    bytes.push(...newline(labels.separator));
    bytes.push(
        ...newline(
            `${padRight(labels.subtotal, 20)}${padLeft(money(payload.subtotal, currency), 22)}`
        )
    );

    payload.taxes?.forEach(tax => {
        bytes.push(
            ...newline(`${padRight(tax.label, 20)}${padLeft(money(tax.amount, currency), 22)}`)
        );
    });

    bytes.push(ESC, 0x45, 0x01);
    bytes.push(
        ...newline(`${padRight(labels.total, 20)}${padLeft(money(payload.total, currency), 22)}`)
    );
    bytes.push(ESC, 0x45, 0x00);

    if (payload.payment_label) {
        bytes.push(...newline(`${labels.payment}: ${payload.payment_label}`));
    }

    if (payload.fiscal_warning) {
        bytes.push(LF, ...newline(payload.fiscal_warning));
    }

    if (payload.fiscal_qr_payload) {
        bytes.push(LF, ESC, 0x61, 0x01);
        bytes.push(...qrSizeBytes(6));
        bytes.push(...qrErrorCorrectionBytes());
        bytes.push(...qrStoreBytes(payload.fiscal_qr_payload));
        bytes.push(...qrPrintBytes(), LF);
        bytes.push(ESC, 0x61, 0x00);
    }

    payload.footer_lines?.forEach(line => {
        bytes.push(...newline(line));
    });

    bytes.push(LF, LF, LF, GS, 0x56, 0x41, 0x10);
    return Uint8Array.from(bytes);
}

/**
 * Query Performance Monitoring Service
 *
 * Addresses PLATFORM_AUDIT finding DB-2: No query performance monitoring
 *
 * This service provides:
 * - Query timing logs for performance tracking
 * - Slow query detection and alerting
 * - Query statistics aggregation
 * - Integration with audit logging
 */

import { logger } from '@/lib/logger';
const log = logger.child('QueryMonitor');

/**
 * Configuration for query monitoring
 */
interface QueryMonitorConfig {
    /** Threshold in ms to log slow queries (default: 1000ms) */
    slowQueryThresholdMs: number;
    /** Whether to log all queries or only slow ones */
    logAllQueries: boolean;
    /** Whether to send alerts for slow queries */
    enableAlerts: boolean;
    /** Sample rate for logging (0-1, where 1 = 100%) */
    sampleRate: number;
}

/**
 * Statistics for a query pattern
 */
interface QueryStats {
    queryName: string;
    totalCalls: number;
    totalTimeMs: number;
    avgTimeMs: number;
    maxTimeMs: number;
    minTimeMs: number;
    slowCalls: number;
    lastExecutedAt: Date;
}

/**
 * Result of a monitored query
 */
interface MonitoredQueryResult<T> {
    data: T;
    durationMs: number;
    isSlowQuery: boolean;
    queryName: string;
}

const DEFAULT_CONFIG: QueryMonitorConfig = {
    slowQueryThresholdMs: 1000,
    logAllQueries: false,
    enableAlerts: true,
    sampleRate: 1.0,
};

/**
 * Query Monitor Service
 *
 * Wraps database queries with performance monitoring and logging.
 */
class QueryMonitorService {
    private config: QueryMonitorConfig;
    private stats: Map<string, QueryStats> = new Map();

    constructor(config: Partial<QueryMonitorConfig> = {}) {
        this.config = { ...DEFAULT_CONFIG, ...config };
    }

    /**
     * Update configuration
     */
    updateConfig(config: Partial<QueryMonitorConfig>): void {
        this.config = { ...this.config, ...config };
    }

    /**
     * Execute a query with monitoring
     *
     * @param queryName - Human-readable name for the query
     * @param queryFn - Function that executes the query
     * @param metadata - Optional metadata for logging
     * @returns Query result with timing information
     *
     * @example
     * ```ts
     * const result = await monitor.executeMonitored(
     *   'fetch_restaurant_menu',
     *   () => supabase.from('menu_items').select('id, name, price').eq('restaurant_id', id),
     *   { restaurantId: id }
     * );
     * ```
     */
    async executeMonitored<T>(
        queryName: string,
        queryFn: () => Promise<T>,
        metadata?: Record<string, unknown>
    ): Promise<MonitoredQueryResult<T>> {
        // Check sampling
        if (Math.random() > this.config.sampleRate) {
            const data = await queryFn();
            return {
                data,
                durationMs: 0,
                isSlowQuery: false,
                queryName,
            };
        }

        const startTime = performance.now();
        let error: Error | null = null;

        try {
            const data = await queryFn();
            const durationMs = performance.now() - startTime;
            const isSlowQuery = durationMs > this.config.slowQueryThresholdMs;

            this.recordStats(queryName, durationMs, isSlowQuery);

            if (this.shouldLog(durationMs)) {
                this.logQuery(queryName, durationMs, metadata, isSlowQuery);
            }

            if (isSlowQuery && this.config.enableAlerts) {
                this.alertSlowQuery(queryName, durationMs, metadata);
            }

            return { data, durationMs, isSlowQuery, queryName };
        } catch (err) {
            const durationMs = performance.now() - startTime;
            error = err instanceof Error ? err : new Error(String(err));

            this.logQuery(queryName, durationMs, metadata, false, error);
            throw error;
        }
    }

    /**
     * Get statistics for all tracked queries
     */
    getStats(): QueryStats[] {
        return Array.from(this.stats.values());
    }

    /**
     * Get statistics for a specific query
     */
    getQueryStats(queryName: string): QueryStats | undefined {
        return this.stats.get(queryName);
    }

    /**
     * Get slow queries (queries with avg time above threshold)
     */
    getSlowQueries(): QueryStats[] {
        return this.getStats().filter(stat => stat.avgTimeMs > this.config.slowQueryThresholdMs);
    }

    /**
     * Reset statistics
     */
    resetStats(): void {
        this.stats.clear();
    }

    /**
     * Get current configuration
     */
    getConfig(): QueryMonitorConfig {
        return { ...this.config };
    }

    /**
     * Record query statistics
     */
    private recordStats(queryName: string, durationMs: number, isSlow: boolean): void {
        const existing = this.stats.get(queryName);

        if (existing) {
            existing.totalCalls++;
            existing.totalTimeMs += durationMs;
            existing.avgTimeMs = existing.totalTimeMs / existing.totalCalls;
            existing.maxTimeMs = Math.max(existing.maxTimeMs, durationMs);
            existing.minTimeMs = Math.min(existing.minTimeMs, durationMs);
            if (isSlow) existing.slowCalls++;
            existing.lastExecutedAt = new Date();
        } else {
            this.stats.set(queryName, {
                queryName,
                totalCalls: 1,
                totalTimeMs: durationMs,
                avgTimeMs: durationMs,
                maxTimeMs: durationMs,
                minTimeMs: durationMs,
                slowCalls: isSlow ? 1 : 0,
                lastExecutedAt: new Date(),
            });
        }
    }

    /**
     * Determine if query should be logged
     */
    private shouldLog(durationMs: number): boolean {
        if (this.config.logAllQueries) return true;
        return durationMs > this.config.slowQueryThresholdMs;
    }

    /**
     * Log query execution
     */
    private logQuery(
        queryName: string,
        durationMs: number,
        metadata?: Record<string, unknown>,
        isSlow = false,
        error?: Error | null
    ): void {
        const logLevel = error ? 'error' : isSlow ? 'warn' : 'info';
        const logData = {
            query: queryName,
            durationMs: Math.round(durationMs * 100) / 100,
            isSlow,
            ...metadata,
            ...(error && { error: error.message }),
        };

        if (error) {
            log.error(`Query failed: ${queryName}`, error, logData);
        } else if (isSlow) {
            log.warn(`Slow query: ${queryName}`, logData);
        } else {
            log.info(`Query executed: ${queryName}`, logData);
        }
    }

    /**
     * Alert on slow query
     */
    private alertSlowQuery(
        queryName: string,
        durationMs: number,
        metadata?: Record<string, unknown>
    ): void {
        log.warn(`SLOW QUERY ALERT: ${queryName} took ${durationMs.toFixed(2)}ms`, metadata);

        // In production, this could:
        // 1. Send to Sentry
        // 2. Write to audit_logs table
        // 3. Send to monitoring service

        // Example: Track in audit_logs (would be called from API route)
        // auditLogger.log({
        //     action: 'slow_query_detected',
        //     entityType: 'query',
        //     entityId: queryName,
        //     metadata: { durationMs, ...metadata },
        // });
    }
}

// Singleton instance
let monitorInstance: QueryMonitorService | null = null;

/**
 * Get the query monitor singleton
 */
export function getQueryMonitor(config?: Partial<QueryMonitorConfig>): QueryMonitorService {
    if (!monitorInstance) {
        monitorInstance = new QueryMonitorService(config);
    } else if (config) {
        monitorInstance.updateConfig(config);
    }
    return monitorInstance;
}

/**
 * Execute a monitored query (convenience function)
 *
 * @param queryName - Human-readable name for the query
 * @param queryFn - Function that executes the query
 * @param metadata - Optional metadata for logging
 * @returns The query result data
 *
 * @example
 * ```ts
 * const menuItems = await monitoredQuery(
 *   'fetch_menu_items',
 *   () => supabase.from('menu_items').select('id, name, price'),
 *   { restaurantId: '123' }
 * );
 * ```
 */
export async function monitoredQuery<T>(
    queryName: string,
    queryFn: () => Promise<T>,
    metadata?: Record<string, unknown>
): Promise<T> {
    const monitor = getQueryMonitor();
    const result = await monitor.executeMonitored(queryName, queryFn, metadata);
    return result.data;
}

/**
 * Time an async operation and return the duration
 *
 * @param name - Name for the timer
 * @param fn - Async function to time
 * @returns Object with result and duration
 */
export async function timeAsync<T>(
    name: string,
    fn: () => Promise<T>
): Promise<{ result: T; durationMs: number }> {
    const start = performance.now();
    const result = await fn();
    const durationMs = performance.now() - start;
    return { result, durationMs };
}

// Export types and class
export type { QueryMonitorConfig, QueryStats, MonitoredQueryResult };
export { QueryMonitorService };

/**
 * Database Connection Pooling Configuration
 * HIGH-016: Configure connection pooling for production load
 *
 * This module provides connection pooling configuration for Supabase/Postgres
 * to handle production load efficiently.
 */

/**
 * Connection pooling configuration
 */
export interface ConnectionPoolConfig {
    /**
     * Maximum number of connections in the pool
     * Default: 10 for serverless, 20 for long-running processes
     */
    maxConnections: number;

    /**
     * Minimum number of connections to maintain
     * Only applicable for long-running processes
     */
    minConnections: number;

    /**
     * Maximum time (ms) to wait for a connection from the pool
     */
    connectionTimeoutMs: number;

    /**
     * Maximum time (ms) a connection can be idle before being closed
     */
    idleTimeoutMs: number;

    /**
     * Connection mode for Supabase
     * - 'transaction': Best for serverless functions (short-lived transactions)
     * - 'session': Best for long-running processes (maintains session state)
     */
    poolMode: 'transaction' | 'session';

    /** Whether app traffic is using the dedicated pooler lane. */
    useSupabasePooler: boolean;
}

/**
 * Default configuration for serverless environments (Vercel, etc.)
 * Uses transaction mode for optimal performance with serverless functions
 */
export const SERVERLESS_POOL_CONFIG: ConnectionPoolConfig = {
    maxConnections: 10,
    minConnections: 0,
    connectionTimeoutMs: 30000, // 30 seconds
    idleTimeoutMs: 30000, // 30 seconds
    poolMode: 'transaction',
    useSupabasePooler: true,
};

/**
 * Default configuration for long-running processes
 * Uses session mode for maintaining prepared statements and session state
 */
export const LONG_RUNNING_POOL_CONFIG: ConnectionPoolConfig = {
    maxConnections: 20,
    minConnections: 2,
    connectionTimeoutMs: 60000, // 60 seconds
    idleTimeoutMs: 300000, // 5 minutes
    poolMode: 'session',
    useSupabasePooler: true,
};

/**
 * Get the appropriate connection pool configuration based on environment
 */
export function getConnectionPoolConfig(): ConnectionPoolConfig {
    const isServerless =
        process.env.VERCEL === '1' ||
        process.env.AWS_LAMBDA_FUNCTION_NAME !== undefined ||
        process.env.NETLIFY === 'true';

    return isServerless ? SERVERLESS_POOL_CONFIG : LONG_RUNNING_POOL_CONFIG;
}

/**
 * Get the app-safe pooler URL.
 * App traffic should never switch to direct connections at runtime.
 */
export function getPooledConnectionUrl(_mode: 'transaction' | 'session' = 'transaction'): string {
    const poolerUrl = process.env.DATABASE_URL ?? process.env.SUPABASE_POOLER_URL;
    if (!poolerUrl) {
        throw new Error('DATABASE_URL is not configured with the Supabase pooler URL');
    }

    if (poolerUrl.includes('@db.') || poolerUrl.includes('.supabase.co:5432')) {
        throw new Error(
            'DATABASE_URL must point to the Supabase pooler, not the direct database host'
        );
    }

    return poolerUrl;
}

/**
 * Get the infra-only direct Postgres URL.
 * Reserved for migrations, CI, admin scripts, and PowerSync replication.
 */
export function getDirectConnectionUrl(): string {
    const directUrl = process.env.DATABASE_DIRECT_URL ?? process.env.SUPABASE_DB_URL;
    if (!directUrl) {
        throw new Error(
            'DATABASE_DIRECT_URL is not configured with the direct Supabase Postgres URL'
        );
    }

    if (directUrl.includes('.pooler.supabase.com:6543') || directUrl.includes('@pooler.')) {
        throw new Error(
            'DATABASE_DIRECT_URL must point to the direct database host, not the Supabase pooler'
        );
    }

    return directUrl;
}

/**
 * Connection pool health check
 * Returns the current pool status for monitoring
 */
export interface PoolHealthStatus {
    healthy: boolean;
    activeConnections: number;
    idleConnections: number;
    waitingRequests: number;
    lastChecked: string;
}

/**
 * BKND-027: Real connection pool health check.
 * Queries pg_stat_activity via service role client for live connection metrics.
 * Falls back to connectivity-only check when pg stats unavailable.
 */
export async function checkPoolHealth(): Promise<PoolHealthStatus> {
    const lastChecked = new Date().toISOString();

    try {
        const { createServiceRoleClient } = await import('./service-role');
        const supabase = createServiceRoleClient();

        // Query pg_stat_activity for real connection counts
        const { data, error } = await supabase
            .from('_prisma_migrations' as never)
            .select('*', { count: 'exact', head: true })
            .limit(0);

        if (error) {
            return {
                healthy: false,
                activeConnections: -1,
                idleConnections: -1,
                waitingRequests: -1,
                lastChecked,
            };
        }

        const poolConfig = getConnectionPoolConfig();

        // Second query: attempt to get pg_stat_activity via RPC if available
        try {
            const { data: stats } = await supabase.rpc('get_pool_stats' as never);
            if (stats && typeof stats === 'object') {
                const s = stats as Record<string, number>;
                return {
                    healthy: true,
                    activeConnections: s.active ?? 0,
                    idleConnections: s.idle ?? 0,
                    waitingRequests: s.waiting ?? 0,
                    lastChecked,
                };
            }
        } catch {
            // RPC not available ΓÇö fall through to basic check
        }

        // Fallback: DB reachable, report pool config
        return {
            healthy: true,
            activeConnections: poolConfig.maxConnections > 0 ? 1 : 0,
            idleConnections: 0,
            waitingRequests: 0,
            lastChecked,
        };
    } catch {
        return {
            healthy: false,
            activeConnections: -1,
            idleConnections: -1,
            waitingRequests: -1,
            lastChecked,
        };
    }
}

/**
 * Configuration for Supabase client with connection pooling
 */
export interface SupabasePoolerConfig {
    db: { schema: string };
    auth: { autoRefreshToken: boolean; persistSession: boolean };
    global: { headers: { 'x-connection-mode': 'transaction' | 'session' } };
}

export function getSupabasePoolerConfig(): SupabasePoolerConfig {
    const config = getConnectionPoolConfig();

    return {
        db: {
            schema: 'public',
        },
        auth: {
            autoRefreshToken: true,
            persistSession: false,
        },
        global: {
            headers: {
                // Add connection pooling headers
                'x-connection-mode': config.poolMode,
            },
        },
    };
}

/**
 * Environment variable documentation for connection pooling
 *
 * Required environment variables:
 *
 * - DATABASE_URL: Supabase pooler URL for app-safe SQL traffic
 * - DATABASE_DIRECT_URL: Direct Postgres URL for infra-only capabilities
 *
 * Optional environment variables:
 *
 * - SUPABASE_POOLER_URL: Alias of DATABASE_URL
 * - SUPABASE_DB_URL: Alias of DATABASE_DIRECT_URL
 * - SUPABASE_REGION: AWS region for legacy pooler endpoint construction
 *
 * Supabase Connection Pooling Setup:
 *
 * 1. Enable connection pooling in Supabase Dashboard:
 *    - Go to Project Settings > Database
 *    - Enable "Connection Pooling"
 *    - Choose "Transaction" mode for serverless
 *
 * 2. Configure environment variables:
 *    DATABASE_URL=postgresql://...pooler...:6543/postgres
 *    DATABASE_DIRECT_URL=postgresql://...db...:5432/postgres
 *
 * 3. For production, ensure these settings in Supabase:
 *    - Pool Size: 15-20 (adjust based on your plan)
 *    - Mode: Transaction (for serverless)
 *
 * Best Practices:
 *
 * - Use transaction mode for serverless functions (Vercel, Netlify)
 * - Use session mode for long-running app workers when needed
 * - Reserve direct connection for migrations, CI, admin scripts, and PowerSync replication
 * - Monitor connection count with pg_stat_activity
 * - Set appropriate timeouts to prevent connection leaks
 * - Use prepared statements only in session mode
 */

const connectionPoolingExports = {
    getConnectionPoolConfig,
    getPooledConnectionUrl,
    getDirectConnectionUrl,
    checkPoolHealth,
    getSupabasePoolerConfig,
    SERVERLESS_POOL_CONFIG,
    LONG_RUNNING_POOL_CONFIG,
};

export default connectionPoolingExports;

/**
 * Reconciliation Replay Worker
 *
 * S3-T5: Processes reconciliation_entries locally after sync,
 * matching local settlement records against provider webhook data.
 */

import { getPowerSync } from './powersync-config';
import { logger } from '@/lib/logger';

export interface ReconciliationEntry {
    id: string;
    restaurant_id: string;
    payment_id: string | null;
    payment_session_id: string | null;
    ledger_type: string;
    ledger_id: string;
    source_type: string;
    source_id: string | null;
    expected_amount: number;
    settled_amount: number;
    delta_amount: number;
    status: string;
    notes: string | null;
    metadata_json: string;
    created_at: string;
    updated_at: string;
}

export interface ReconciliationResult {
    processed: number;
    matched: number;
    mismatched: number;
    disputed: number;
    errors: string[];
}

export async function processPendingReconciliation(
    limit: number = 50
): Promise<ReconciliationResult> {
    const db = getPowerSync();
    const result: ReconciliationResult = {
        processed: 0,
        matched: 0,
        mismatched: 0,
        disputed: 0,
        errors: [],
    };

    if (!db) {
        result.errors.push('PowerSync not initialized');
        return result;
    }

    try {
        const entries = await db.getAllAsync<ReconciliationEntry>(
            `SELECT * FROM reconciliation_entries
             WHERE status IN ('pending', 'matched')
             ORDER BY created_at ASC
             LIMIT ?`,
            [limit]
        );

        if (!entries || entries.length === 0) {
            return result;
        }

        for (const entry of entries) {
            result.processed++;

            try {
                const delta = Math.abs(Number(entry.delta_amount ?? 0));

                if (delta <= 0.01) {
                    await db.execute(
                        `UPDATE reconciliation_entries
                         SET status = 'verified', updated_at = ?
                         WHERE id = ?`,
                        [new Date().toISOString(), entry.id]
                    );
                    result.matched++;
                } else {
                    await db.execute(
                        `UPDATE reconciliation_entries
                         SET status = ?, notes = ?, updated_at = ?
                         WHERE id = ?`,
                        [
                            delta > 100 ? 'disputed' : 'mismatched',
                            `Local settled=${entry.settled_amount}, expected=${entry.expected_amount}, delta=${entry.delta_amount}`,
                            new Date().toISOString(),
                            entry.id,
                        ]
                    );

                    if (delta > 100) {
                        result.disputed++;
                    } else {
                        result.mismatched++;
                    }
                }
            } catch (entryError) {
                result.errors.push(
                    `Entry ${entry.id}: ${entryError instanceof Error ? entryError.message : 'Unknown error'}`
                );
            }
        }
    } catch (error) {
        result.errors.push(
            `Reconciliation failed: ${error instanceof Error ? error.message : 'Unknown error'}`
        );
    }

    return result;
}

export async function getReconciliationStats(): Promise<{
    total: number;
    pending: number;
    matched: number;
    mismatched: number;
    disputed: number;
}> {
    const db = getPowerSync();
    if (!db) {
        return { total: 0, pending: 0, matched: 0, mismatched: 0, disputed: 0 };
    }

    const [total, pending, matched, mismatched, disputed] = await Promise.all([
        db.getFirstAsync<{ count: number }>(`SELECT COUNT(*) as count FROM reconciliation_entries`),
        db.getFirstAsync<{ count: number }>(
            `SELECT COUNT(*) as count FROM reconciliation_entries WHERE status = 'pending'`
        ),
        db.getFirstAsync<{ count: number }>(
            `SELECT COUNT(*) as count FROM reconciliation_entries WHERE status IN ('matched', 'verified')`
        ),
        db.getFirstAsync<{ count: number }>(
            `SELECT COUNT(*) as count FROM reconciliation_entries WHERE status = 'mismatched'`
        ),
        db.getFirstAsync<{ count: number }>(
            `SELECT COUNT(*) as count FROM reconciliation_entries WHERE status = 'disputed'`
        ),
    ]);

    return {
        total: (total?.count ?? 0) as number,
        pending: (pending?.count ?? 0) as number,
        matched: (matched?.count ?? 0) as number,
        mismatched: (mismatched?.count ?? 0) as number,
        disputed: (disputed?.count ?? 0) as number,
    };
}

/**
 * Sync Worker
 *
 * CRIT-05: Offline sync consolidation
 * Handles background sync between local PowerSync and server
 */

import {
    getPendingSyncOperations,
    markSyncOperationCompleted,
    markSyncOperationFailed,
    getSyncQueueStatus,
} from './idempotency';
import { logger } from '@/lib/logger';
import { reconcileWithServer } from './conflict-resolution';

/**
 * Sync operation row type from the database
 */
interface SyncOperationRow {
    id: string;
    operation: string;
    table_name: string;
    record_id: string;
    payload: string;
    idempotency_key: string;
    attempts: number;
    last_error: string | null;
    created_at: string;
}

/**
 * HIGH-013: API endpoint configuration for sync operations
 * Uses the unified /api/v1/system/sync endpoint for batch operations
 */
const SYNC_API_ENDPOINT = '/api/v1/system/sync';

/**
 * Individual table endpoints for direct operations (fallback)
 */
const SYNC_ENDPOINTS: Record<string, string> = {
    orders: '/api/v1/merchant/operations/orders',
    order_items: '/api/v1/merchant/operations/orders/items',
    kds_order_items: '/api/v1/merchant/operations/kds/items',
    tables: '/api/v1/pos/device/tables',
    payments: '/api/v1/merchant/operations/payments',
    guests: '/api/v1/merchant/guests',
} as const;

/**
 * Cache of endpoint health status (table_name ΓåÆ reachable boolean)
 */
let endpointHealthCache: Record<string, boolean> = {};

/**
 * Validate configured sync endpoints via HEAD request.
 * Skips tables with unreachable endpoints in subsequent sync cycles.
 */
async function validateSyncEndpoints(): Promise<void> {
    const health: Record<string, boolean> = {};

    await Promise.all(
        Object.entries(SYNC_ENDPOINTS).map(async ([tableName, endpoint]) => {
            try {
                const response = await fetch(endpoint + '/_health', {
                    method: 'HEAD',
                    signal: AbortSignal.timeout(5000),
                });
                health[tableName] = response.ok;
            } catch {
                health[tableName] = false;
            }
        })
    );

    try {
        const batchResponse = await fetch(SYNC_API_ENDPOINT + '/_health', {
            method: 'HEAD',
            signal: AbortSignal.timeout(5000),
        });
        health['batch'] = batchResponse.ok;
    } catch {
        health['batch'] = false;
    }

    endpointHealthCache = health;

    const unhealthy = Object.entries(health).filter(([, ok]) => !ok);
    if (unhealthy.length > 0) {
        logger.warn('[SyncWorker] Unreachable endpoints', {
            endpoints: unhealthy.map(([name]) => name),
        });
    }
}

/**
 * Check if a table's endpoint is reachable.
 * If health cache is empty (never validated), assume reachable.
 */
function isEndpointReachable(tableName: string): boolean {
    if (Object.keys(endpointHealthCache).length === 0) {
        return true; // Not yet validated, assume reachable
    }
    return endpointHealthCache[tableName] !== false;
}

/**
 * Exponential backoff configuration
 */
const MAX_RETRIES = 3;
const BASE_DELAY_MS = 1000;
const MAX_DELAY_MS = 30000;

/**
 * Sync event types for UI updates
 */
export type SyncEventType =
    | 'sync:start'
    | 'sync:complete'
    | 'sync:error'
    | 'sync:conflict'
    | 'sync:offline'
    | 'sync:online'
    | 'operation:success'
    | 'operation:failed'
    | 'operation:retry';

/**
 * Sync event payload
 */
export interface SyncEvent {
    type: SyncEventType;
    timestamp: string;
    data?: Record<string, unknown>;
}

/**
 * Sync event listener
 */
export type SyncEventListener = (event: SyncEvent) => void;

/**
 * Sync worker configuration
 */
export interface SyncWorkerConfig {
    /** Interval in ms for checking pending operations */
    syncIntervalMs: number;
    /** Maximum operations per sync batch */
    batchSize: number;
    /** Enable printer queue processing */
    enablePrinterQueue: boolean;
    /** Callback for sync events */
    onSyncProgress?: (stats: SyncProgress) => void;
    /** Callback for errors */
    onError?: (error: Error) => void;
    /** Callback for sync events (HIGH-005) */
    onSyncEvent?: (event: SyncEvent) => void;
}

/**
 * Sync progress statistics
 */
export interface SyncProgress {
    pendingOperations: number;
    completedOperations: number;
    failedOperations: number;
    printerJobsProcessed: number;
    printerJobsSucceeded: number;
    printerJobsFailed: number;
    lastSyncAt: string | null;
    isOnline: boolean;
    /** Number of conflicts detected in last sync */
    conflictsDetected?: number;
}

const DEFAULT_CONFIG: SyncWorkerConfig = {
    syncIntervalMs: 5000, // 5 seconds
    batchSize: 20,
    enablePrinterQueue: true,
};

/**
 * Create a sync worker
 */
export interface SyncWorker {
    start: () => void;
    stop: () => void;
    syncOnce: () => Promise<SyncProgress>;
    getStatus: () => Promise<SyncProgress>;
    readonly isRunning: boolean;
}

export function createSyncWorker(config: Partial<SyncWorkerConfig> = {}): SyncWorker {
    const cfg = { ...DEFAULT_CONFIG, ...config };

    let isRunning = false;
    let intervalId: ReturnType<typeof setInterval> | null = null;
    let lastSyncAt: string | null = null;
    let conflictsDetected = 0;

    /**
     * HIGH-005: Emit sync event for UI updates
     */
    function emitEvent(type: SyncEventType, data?: Record<string, unknown>): void {
        if (cfg.onSyncEvent) {
            cfg.onSyncEvent({
                type,
                timestamp: new Date().toISOString(),
                data,
            });
        }
    }

    /**
     * HIGH-013: Calculate exponential backoff delay
     */
    function calculateBackoffDelay(retryCount: number): number {
        const delay = Math.min(BASE_DELAY_MS * Math.pow(2, retryCount), MAX_DELAY_MS);
        // Add jitter to prevent thundering herd
        return delay + Math.random() * 1000;
    }

    /**
     * HIGH-013: Execute batch sync via unified /api/sync endpoint
     * This is more efficient than individual API calls
     */
    async function executeBatchSync(operations: SyncOperationRow[]): Promise<{
        succeeded: number;
        failed: number;
        results: Map<string, { success: boolean; error?: string }>;
    }> {
        const results = new Map<string, { success: boolean; error?: string }>();
        let succeeded = 0;
        let failed = 0;

        if (operations.length === 0) {
            return { succeeded, failed, results };
        }

        // Transform operations to sync API format
        const syncOperations = operations.map(op => {
            let payload;
            try {
                payload = op.payload ? JSON.parse(op.payload) : {};
            } catch {
                payload = {};
            }

            return {
                id: crypto.randomUUID(),
                operation: op.operation.toLowerCase(),
                tableName: op.table_name,
                recordId: op.record_id,
                data: payload,
                version: 1,
                lastModified: new Date().toISOString(),
                idempotencyKey: op.idempotency_key || `sync-${op.id}`,
                restaurantId: payload.restaurant_id || '',
            };
        });

        try {
            const response = await fetch(SYNC_API_ENDPOINT, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    operations: syncOperations,
                    clientId: `sync-worker-${Date.now()}`,
                }),
            });

            if (!response.ok) {
                // Batch failed - fall back to individual operations
                logger.info('Batch sync failed, falling back to individual operations');
                for (const op of operations) {
                    const result = await executeSyncOperation(op);
                    results.set(op.id, result);
                    if (result.success) {
                        succeeded++;
                    } else {
                        failed++;
                    }
                    if (result.conflict) {
                        emitEvent('sync:conflict', {
                            operationId: op.id,
                            tableName: op.table_name,
                            recordId: op.record_id,
                        });
                    }
                }
                return { succeeded, failed, results };
            }

            const data = await response.json();

            // Process results from batch response
            if (data.data?.results && Array.isArray(data.data.results)) {
                for (let i = 0; i < operations.length; i++) {
                    const op = operations[i];
                    const result = data.data.results[i];
                    if (result) {
                        results.set(op.id, { success: result.success, error: result.error });
                        if (result.success) {
                            succeeded++;
                        } else {
                            failed++;
                        }
                        if (result.conflict || result.error?.includes('conflict')) {
                            conflictsDetected++;
                            emitEvent('sync:conflict', {
                                operationId: op.id,
                                tableName: op.table_name,
                                recordId: op.record_id,
                            });
                        }
                    }
                }
            }

            return { succeeded, failed, results };
        } catch (error) {
            logger.error('Batch sync error', error);
            // Fall back to individual operations
            for (const op of operations) {
                const result = await executeSyncOperation(op);
                results.set(op.id, result);
                if (result.success) {
                    succeeded++;
                } else {
                    failed++;
                }
                if (result.conflict) {
                    emitEvent('sync:conflict', {
                        operationId: op.id,
                        tableName: op.table_name,
                        recordId: op.record_id,
                    });
                }
            }
            return { succeeded, failed, results };
        }
    }

    /**
     * HIGH-013: Make actual API call to server for sync operation (fallback)
     */
    async function executeSyncOperation(
        op: SyncOperationRow
    ): Promise<{ success: boolean; error?: string; conflict?: boolean }> {
        const endpoint = SYNC_ENDPOINTS[op.table_name];

        if (!endpoint) {
            logger.info('No endpoint configured for table', { tableName: op.table_name });
            return { success: false, error: `Unknown table: ${op.table_name}` };
        }

        const method =
            op.operation === 'INSERT' || op.operation === 'create'
                ? 'POST'
                : op.operation === 'UPDATE' || op.operation === 'update'
                  ? 'PATCH'
                  : 'DELETE';
        const url =
            method === 'DELETE' || method === 'PATCH' ? `${endpoint}/${op.record_id}` : endpoint;

        try {
            const response = await fetch(url, {
                method,
                headers: {
                    'Content-Type': 'application/json',
                    'x-sync-operation-id': String(op.id),
                    'x-idempotency-key': op.idempotency_key || String(op.id),
                },
                body: method !== 'DELETE' ? op.payload : undefined,
            });

            const responseData = (await response.json().catch(() => ({}))) as {
                error?: { message?: string } | string;
                data?: Record<string, unknown>;
            };

            if (!response.ok) {
                if (response.status === 409) {
                    conflictsDetected++;
                    return {
                        success: false,
                        error: `Conflict detected for ${op.table_name}/${op.record_id}`,
                        conflict: true,
                    };
                }
                const errorMessage =
                    typeof responseData.error === 'object'
                        ? responseData.error?.message || `HTTP ${response.status}`
                        : responseData.error || `HTTP ${response.status}`;
                return {
                    success: false,
                    error: errorMessage,
                };
            }

            // HIGH-006: Reconcile local data with server response
            if (responseData?.data && method !== 'DELETE') {
                try {
                    await reconcileWithServer({
                        entityType: op.table_name,
                        entityId: op.record_id,
                        serverData: responseData.data,
                    });
                } catch {
                    // Reconciliation failure is non-critical - the sync succeeded
                }
            }

            return { success: true };
        } catch (error) {
            return {
                success: false,
                error: error instanceof Error ? error.message : String(error),
            };
        }
    }

    /**
     * Process pending sync operations with retry logic
     * Uses batch sync for efficiency
     */
    async function processSyncOperations(): Promise<{
        processed: number;
        succeeded: number;
        failed: number;
    }> {
        const operations = await getPendingSyncOperations(cfg.batchSize);

        if (operations.length === 0) {
            return { processed: 0, succeeded: 0, failed: 0 };
        }

        logger.info('Processing operations via batch sync', { count: operations.length });

        // Use batch sync for efficiency
        const { succeeded, failed, results } = await executeBatchSync(operations);

        // Mark operations as completed or failed based on results
        for (const op of operations) {
            const result = results.get(op.id);
            if (result?.success) {
                await markSyncOperationCompleted(op.id);
            } else if (result) {
                const retryCount = op.attempts || 0;
                if (retryCount >= MAX_RETRIES) {
                    await markSyncOperationFailed(op.id, result.error || 'Max retries exceeded');
                    cfg.onError?.(new Error(result.error || 'Sync operation failed'));
                }
            }
        }

        return { processed: operations.length, succeeded, failed };
    }

    /**
     * Process pending print jobs
     */
    async function processPrinterQueue(): Promise<{
        processed: number;
        succeeded: number;
        failed: number;
    }> {
        // This would integrate with the actual printer system
        // For now, just return zeros as we can't print from server
        return { processed: 0, succeeded: 0, failed: 0 };
    }

    /**
     * Get current sync status
     */
    async function getStatus(): Promise<SyncProgress> {
        const queueStats = await getSyncQueueStatus();

        return {
            pendingOperations: queueStats.pending,
            completedOperations: queueStats.completed,
            failedOperations: queueStats.failed,
            printerJobsProcessed: 0,
            printerJobsSucceeded: 0,
            printerJobsFailed: 0,
            lastSyncAt,
            isOnline: typeof navigator !== 'undefined' ? navigator.onLine : true,
            conflictsDetected,
        };
    }

    /**
     * Run one sync cycle
     */
    async function syncOnce(): Promise<SyncProgress> {
        if (!navigator.onLine) {
            logger.info('Offline - skipping sync');
            emitEvent('sync:offline', { reason: 'navigator.offline' });
            return getStatus();
        }

        logger.info('Starting sync cycle');
        emitEvent('sync:start', { timestamp: new Date().toISOString() });

        // Validate endpoint health before processing (every 5th cycle)
        if (Math.random() < 0.2) {
            await validateSyncEndpoints();
        }

        try {
            const syncResult = await processSyncOperations();

            let _printerResult = { processed: 0, succeeded: 0, failed: 0 };
            if (cfg.enablePrinterQueue) {
                _printerResult = await processPrinterQueue();
            }

            lastSyncAt = new Date().toISOString();

            // Emit success/failure events
            if (syncResult.succeeded > 0) {
                emitEvent('operation:success', {
                    count: syncResult.succeeded,
                    processed: syncResult.processed,
                });
            }

            if (syncResult.failed > 0) {
                emitEvent('operation:failed', {
                    count: syncResult.failed,
                    processed: syncResult.processed,
                });
            }

            const status = await getStatus();
            cfg.onSyncProgress?.(status);

            logger.info('Sync complete', {
                succeeded: syncResult.succeeded,
                failed: syncResult.failed,
            });

            emitEvent('sync:complete', {
                succeeded: syncResult.succeeded,
                failed: syncResult.failed,
                processed: syncResult.processed,
                conflictsDetected,
            });

            return status;
        } catch (error) {
            const errorMessage = error instanceof Error ? error.message : 'Unknown error';
            logger.error('Sync error', errorMessage);

            emitEvent('sync:error', {
                error: errorMessage,
                timestamp: new Date().toISOString(),
            });

            cfg.onError?.(error instanceof Error ? error : new Error(errorMessage));

            throw error;
        }
    }

    /**
     * Start the sync worker
     */
function start(): void {
        if (isRunning) return;

        isRunning = true;
        intervalId = setInterval(syncOnce, cfg.syncIntervalMs);

        // Run immediately on start
        syncOnce();

        logger.info('SyncWorker started');
    }

    /**
     * Stop the sync worker
     */
function stop(): void {
        if (!isRunning) return;

        if (intervalId) {
            clearInterval(intervalId);
            intervalId = null;
        }

        isRunning = false;
        logger.info('SyncWorker stopped');
    }

    return {
        start,
        stop,
        syncOnce,
        getStatus,
        get isRunning() {
            return isRunning;
        },
    };
}

/**
 * Singleton sync worker instance
 */
let syncWorker: ReturnType<typeof createSyncWorker> | null = null;

/**
 * Get the sync worker instance
 */
export function getSyncWorker(): SyncWorker {
    if (!syncWorker) {
        syncWorker = createSyncWorker();
    }
    return syncWorker;
}

/**
 * Start the global sync worker
 */
export function startGlobalSync(): void {
    const worker = getSyncWorker();
    worker.start();
}

/**
 * Stop the global sync worker
 */
export function stopGlobalSync(): void {
    const worker = getSyncWorker();
    worker.stop();
}

/**
 * Trigger a manual sync
 */
export async function triggerSync(): Promise<SyncProgress> {
    const worker = getSyncWorker();
    return worker.syncOnce();
}
